package pythonparser

import (
	"testing"

	"github.com/stretchr/testify/require"
)

func TestDetectUnsupportedTemplate(t *testing.T) {
	templates := map[string]string{
		"block tag":       "{% include 'partials/common.py' %}\n",
		"expression":      "{{ value }}\n",
		"comment":         "{# generated by cookiecutter #}\n",
		"indented tag":    "    {% if debug %}\n",
		"content first":   "import os\n\n{% include 'x.py' %}\n",
		"scaffold import": "from ${app_name} import views\n",
		"scaffold name":   "${module_name} = 1\n",
	}
	for name, src := range templates {
		t.Run(name, func(t *testing.T) {
			require.NotNil(t, DetectUnsupportedTemplate(src), "expected template detection")
		})
	}

	// The detector runs only after the Python 3 parser failed. These sources are
	// valid Python and never reach it.
	py := map[string]string{
		"inline expression": "value = '{{ name }}'\n",
		"inline block tag":  "value = '{% include x %}'\n",
		"dict literal":      "value = {\"a\": 1}\n",
		"empty":             "",
	}
	for name, src := range py {
		t.Run("python/"+name, func(t *testing.T) {
			require.Nil(t, DetectUnsupportedTemplate(src), "must not classify Python as a template")
		})
	}
}

func TestUnsupportedTemplateReason(t *testing.T) {
	err := DetectUnsupportedTemplate("{% include 'x.py' %}\n")
	require.NotNil(t, err)
	require.Equal(t, "template syntax: jinja block tag", err.UnsupportedSyntaxReason())
}
